import {FRAMES,dateLabel,normalize,search,activeAt,nearestFrame,readStore,saveStore,answerIsCorrect,validStep,validateContent} from './core.mjs';
import {motif,citySVG} from './visuals.mjs';
import {JOURNEYS} from './journeys.mjs';
const main=document.querySelector('main'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let DATA,items=[],civs=[],sources={},state,storage,liveMap=null,markers=[],mapIndex=4,currentType='all',quizAnswers={},toastTimer;
const escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const CIV_COLORS={egypt:'#e6b450',greece:'#4fa3e3',rome:'#e0564f',china:'#f08a3c',umayyad:'#efe6cf',abbasid:'#a48cff',andalus:'#2ec4b0','first-saudi':'#5cc172',persia:'#d16ba5',ottoman:'#ff6b6b'};const civColor=id=>CIV_COLORS[id]||'#d6b477';
const types={civilization:'حضارة ودولة',city:'مدينة',person:'شخصية',event:'حدث',science:'علوم واكتشافات'};
try{storage=localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error()}}}state=readStore(storage);
const byId=id=>items.find(x=>x.id===id);
const href=id=>`#/topic/${encodeURIComponent(id)}`;
const sourceLinks=ids=>`<ul class="source-list">${[...new Set(ids||[])].map(id=>sources[id]?`<li><a href="${escape(sources[id].url)}" target="_blank" rel="noopener noreferrer">${escape(sources[id].title)} ↗</a><small>${escape(sources[id].type||'مصدر تاريخي')} · اطلعنا عليه في 12 أكتوبر 2026</small></li>`:'').join('')}</ul>`;
function persist(){const ok=saveStore(storage,state);if(!ok)toast('تعذر حفظ التقدم على هذا المتصفح؛ سيبقى لهذه الجلسة فقط.');return ok}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3800)}
const head=(title,description,eyebrow='اكتشف. اربط. افهم.')=>`<div class="container page-head reveal"><div class="breadcrumb"><a href="#/">الرئيسية</a> / ${escape(title)}</div><div class="eyebrow">${eyebrow}</div><h1>${escape(title)}</h1><p>${escape(description)}</p></div>`;
function card(c){return `<a class="civ-card" href="${href(c.id)}">${motif(c.id)}<small>${escape(c.region)}</small><h3>${escape(c.title)}</h3><small>${escape(c.periodLabel)}</small></a>`}
function result(x){return `<a class="result-card" href="${href(x.id)}"><span class="badge">${types[x.type]||'موضوع'}</span><h3>${escape(x.title)}</h3><p>${escape(x.summary.slice(0,170))}${x.summary.length>170?'…':''}</p></a>`}
function sectionTitle(n,title,desc,link,label){return `<div class="section-head"><div><div class="eyebrow">${n}</div><h2>${title}</h2><p>${desc}</p></div>${link?`<a class="text-link" href="${link}">${label} ←</a>`:''}</div>`}
function journeyCard(j){const p=state.journeys[j.id]||{};let done=Array.isArray(p.done)?p.done.length:0;return `<a href="#/journey/${j.id}" class="journey-card"><span class="num">0${JOURNEYS.indexOf(j)+1}</span><h3>${j.title}</h3><p>${j.subtitle}</p><span class="muted">3 محطات · أسئلة فهم · حفظ محلي</span><div class="progress-track"><span style="width:${done/3*100}%"></span></div><span class="text-link">${done===3?'راجع الرحلة':done?'تابع رحلتك':'ابدأ الرحلة'} ← <small>${done}/3</small></span></a>`}
function home(){main.innerHTML=`<section class="hero"><div class="hero-content reveal"><div class="eyebrow">أطلس التاريخ التفاعلي <span class="latin"> / ATLAS</span></div><h1>التاريخ ليس مجرد أحداث…<br>إنه عالم ينتظر أن <em>تكتشفه.</em></h1><p>اعبر العصور، استكشف الحضارات، وافهم كيف ارتبطت قصص الإنسان بالأماكن التي عاش فيها.</p><div class="actions"><a class="primary" href="#/encyclopedia">ابدأ الاستكشاف <span>←</span></a><a class="secondary" href="#/atlas">استكشف الخريطة <span>⌖</span></a></div></div><div class="hero-bottom"><span>المشهد تصور فني مولد، يجمع رموزًا من عصور مختلفة؛ ليس صورة أثرية.</span><span class="coords" dir="ltr">A JOURNEY THROUGH HUMAN HISTORY</span></div></section><div class="intro-line"><span><b>${String(civs.length).padStart(2,'0')}</b> موضوعات حضارية</span><span><b>07</b> لقطات زمنية</span><span><b>03</b> رحلات تعليمية</span><span>كل موضوع يبدأ بسؤال وينتهي بفهم.</span></div>
<section class="container section">${sectionTitle('01 / عبر الزمن','كل عصر… نافذة إلى عالم آخر.','اختر حقبة، ثم تتبع الحضارات والمواقع المرتبطة بها.')}<div class="era-list">${[['01','العالم القديم','1400 ق.م',0],['02','العصر الكلاسيكي','400 ق.م — 117 م',2],['03','العصور الإسلامية','700 — 850 م',4],['04','عالم مترابط','1000 م',5],['05','بدايات حديثة','1750 م',6]].map(x=>`<a class="era" href="#/atlas?frame=${x[3]}"><span class="era-number">${x[0]}</span><strong>${x[1]}</strong><small>${x[2]} ←</small></a>`).join('')}</div></section>
<section class="container section" style="padding-top:15px">${sectionTitle('02 / قصص الحضارات','حضارات صنعت التاريخ',`${civs.length} أبواب إلى السياسة والفن والمعرفة والحياة اليومية.`,'#/encyclopedia','الموسوعة كاملة')}<div class="civ-grid">${civs.map(card).join('')}</div><p class="map-note">الرسوم على البطاقات رموز معمارية أصلية؛ ليست إعادة بناء أثرية.</p></section>
<section class="map-feature section"><div class="container">${sectionTitle('03 / المكان والزمان','العالم عبر الزمن','حرّك الزمن. اختر مدينة. اكتشف القصة.','#/atlas','افتح الأطلس')} ${mapShell(false)}</div></section>
<section class="container section">${sectionTitle('04 / نقاط التحول','أحداث غيّرت العالم','افهم الحدث في سياقه: أين وقع، وماذا تغير بعده؟','#/encyclopedia?type=event','كل الأحداث')}<div class="events-list">${items.filter(x=>x.type==='event').slice(0,3).sort((a,b)=>a.start-b.start).map(x=>`<a class="event-card" href="${href(x.id)}"><span class="date">${escape(x.periodLabel)}</span><h3>${escape(x.title)}</h3><p>${escape(x.summary.slice(0,140))}…</p><span class="text-link">اكتشف الحدث ←</span></a>`).join('')}</div></section>
<section class="container section" style="padding-top:10px">${sectionTitle('05 / تعلّم بالاستكشاف','رحلتك أعمق من قراءة مقال','محطات قصيرة، روابط على الخريطة، وأسئلة تتأكد بها من فهمك.','#/journeys','جميع الرحلات')}<div class="journey-grid">${JOURNEYS.map(journeyCard).join('')}</div></section>
<section class="container section"><div class="city-feature"><div class="city-art">${citySVG()}</div><div><div class="eyebrow">06 / مدن لها حكاية</div><h2>بغداد.<br>مدينة دائرية، وأثر يتجاوز الحدود.</h2><p>استكشف تصورًا تعليميًا للمدينة المدورة. اضغط معالمها لتتعرف على وظائفها، وتفرق بين ما ترويه المصادر وما يتخيله الرسم.</p><a class="primary" href="#/city">ادخل المدينة <span>←</span></a><p class="map-note">رسم أصلي مبسط؛ لا يمثل قياسًا أو توزيعًا أثريًا دقيقًا.</p></div></div></section>
<section class="container section"><div class="fact"><span class="fact-mark">“</span><div><div class="eyebrow">07 / اكتشف معلومة</div><h3>لم تكن اليونان القديمة دولة موحدة.</h3><p>ضمت مدنًا مثل أثينا وإسبرطة، لكل منها مؤسساتها وتاريخها. كلمة «حضارة» أوسع من حدود دولة واحدة.</p><a class="text-link" href="${href('greece')}">افهم عالم المدن اليونانية ومصادره ←</a></div></div></section>`;mountMap(false)}
function mapShell(full){return `<div class="${full?'full-map':''}"><div class="map-layout"><div class="map-stage"><div id="map" class="map-canvas" role="region" aria-label="الخريطة الجغرافية للمواقع التاريخية"></div><div class="map-top-tag">مواقع موثقة · بلا حدود سياسية</div><div class="map-legend" id="map-legend"></div><div class="map-halo-note">الهالات الملونة تمييز للحضارات، لا تمثل حدود نفوذ</div></div><aside class="map-side" aria-live="polite" id="map-side"></aside></div><div class="timeline-controls"><div class="timeline-line"><button data-frame-move="-1" aria-label="الفترة السابقة">→</button><output id="year-label" for="year-slider"></output><input id="year-slider" type="range" min="0" max="6" step="1" value="${mapIndex}" aria-label="اختر لقطة تاريخية" aria-valuetext="${dateLabel(FRAMES[mapIndex])}"><button data-frame-move="1" aria-label="الفترة التالية">←</button></div><div class="frame-list">${FRAMES.map((y,i)=>`<button data-frame="${i}" class="${i===mapIndex?'active':''}">${dateLabel(y)}</button>`).join('')}</div><p class="map-note">سبع لقطات تعليمية، وليست بيانات دقيقة لكل سنة. اليابسة من Natural Earth وتصف جغرافيا عامة معاصرة؛ لا تعيد رسم السواحل القديمة. مواقع المدن تقريبية، وليست حدود نفوذ. الألوان تميّز الحضارات، والهالات حول المدن للتمييز البصري فقط؛ التضاريس والأنهار من Natural Earth بصورتها المعاصرة.</p></div></div>`}
function activePoints(){let year=FRAMES[mapIndex],q=document.getElementById('map-query')?.value||'',cityOn=document.getElementById('layer-city')?.checked!==false,eventOn=document.getElementById('layer-event')?.checked===true;let cs=activeAt(civs,year).filter(c=>!q||normalize([c.title,byId(c.cityId)?.title].join(' ')).includes(normalize(q)));let points=cityOn?cs.map(c=>({id:c.cityId,title:byId(c.cityId)?.title||c.title,point:c.point,civ:c.id,type:'city'})):[];if(eventOn)points.push(...items.filter(x=>x.type==='event'&&x.point&&x.start<=year&&cs.some(c=>c.id===x.civId)).map(x=>({...x,civ:x.civId})));return points}
function declutter(){if(!liveMap)return;const pos=[];for(const m of markers){const b=liveMap.project(m.getLngLat()),n=pos.filter(q=>Math.hypot(q.x-b.x,q.y-b.y)<34).length;m.setOffset(n?[16,-14-(n-1)*22]:[0,0]);pos.push(b)}requestAnimationFrame(()=>{const box=document.getElementById('map').getBoundingClientRect(),dots=markers.map(m=>m.getElement().getBoundingClientRect()),seen=[],hit=(r,v,g=3)=>r.left<v.right+g&&r.right>v.left-g&&r.top<v.bottom+g&&r.bottom>v.top-g;markers.forEach((m,i)=>{const el=m.getElement(),s=el.querySelector('span');if(!s)return;s.style.visibility='';const r=s.getBoundingClientRect(),ev=el.classList.contains('event');const bad=seen.some(v=>hit(r,v))||(ev&&(dots.some((d,j)=>j!==i&&hit(r,d,1))||r.left<box.left||r.right>box.right||r.top<box.top));if(bad)s.style.visibility='hidden';else seen.push(r)})})}
function graticule(){const f=[];for(let x=-180;x<=180;x+=15)f.push({type:'Feature',properties:{},geometry:{type:'LineString',coordinates:Array.from({length:37},(_,i)=>[x,-90+i*5])}});for(let y=-75;y<=75;y+=15)f.push({type:'Feature',properties:{},geometry:{type:'LineString',coordinates:Array.from({length:73},(_,i)=>[-180+i*5,y])}});return{type:'FeatureCollection',features:f}}
function mapStyle(){const NE='<a href="https://www.naturalearthdata.com/">Natural Earth</a> · Public domain';return{version:8,sources:{land:{type:'geojson',data:'assets/land.geojson',attribution:NE},phys:{type:'geojson',data:'assets/physical.geojson'},water:{type:'geojson',data:'assets/water.geojson'},grid:{type:'geojson',data:graticule()},halo:{type:'geojson',data:{type:'FeatureCollection',features:[]}}},layers:[
{id:'ocean',type:'background',paint:{'background-color':'#0c2233'}},
{id:'grid',type:'line',source:'grid',paint:{'line-color':'#c5a46d','line-opacity':.09,'line-width':.6,'line-dasharray':[2,3]}},
{id:'shelf',type:'line',source:'land',paint:{'line-color':'#2f6f8c','line-width':['interpolate',['linear'],['zoom'],1,4,5,7],'line-blur':['interpolate',['linear'],['zoom'],1,3,5,5],'line-opacity':.4}},
{id:'land',type:'fill',source:'land',paint:{'fill-color':'#33473b'}},
{id:'plateau',type:'fill',source:'phys',filter:['==',['get','c'],'p'],paint:{'fill-color':'#4a5a3e','fill-opacity':.55}},
{id:'desert',type:'fill',source:'phys',filter:['==',['get','c'],'d'],paint:{'fill-color':'#a3824c','fill-opacity':.5}},
{id:'mountain',type:'fill',source:'phys',filter:['==',['get','c'],'m'],paint:{'fill-color':'#6b5240','fill-opacity':.7}},
{id:'mountain-edge',type:'line',source:'phys',filter:['==',['get','c'],'m'],paint:{'line-color':'#a07f5c','line-opacity':.35,'line-width':.6}},
{id:'coast',type:'line',source:'land',paint:{'line-color':'#c5a46d','line-opacity':.55,'line-width':['interpolate',['linear'],['zoom'],1,.5,6,1.2]}},
{id:'lakes',type:'fill',source:'water',filter:['has','lake'],paint:{'fill-color':'#1d4d66','fill-outline-color':'#5fa8cf'}},
{id:'rivers',type:'line',source:'water',filter:['!',['has','lake']],layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':'#5fa8cf','line-opacity':['interpolate',['linear'],['zoom'],1,.55,4,.9],'line-width':['interpolate',['linear'],['zoom'],1,['match',['get','r'],1,1.1,2,.9,3,.8,.4],6,['match',['get','r'],1,3,2,2.4,3,2,1.2]]}},
{id:'halo',type:'circle',source:'halo',paint:{'circle-color':['get','color'],'circle-opacity':.38,'circle-blur':.9,'circle-radius':['interpolate',['exponential',2],['zoom'],1,22,4,80,8,600]}}]}}
let geoLabels=null,geoMarkers=[];
function mountGeoLabels(){if(!liveMap)return;const add=()=>{for(const m of geoMarkers)m.remove();geoMarkers=geoLabels.map(l=>{const e=document.createElement('div');e.className='geo-label geo-'+l.k;e.textContent=l.n;e.dataset.z=l.z;return new maplibregl.Marker({element:e}).setLngLat(l.p).addTo(liveMap)});zoomGeoLabels()};if(geoLabels)add();else fetch('assets/geo-labels.json').then(r=>r.json()).then(j=>{geoLabels=j;if(liveMap)add()}).catch(()=>{})}
function zoomGeoLabels(){if(!liveMap)return;const z=liveMap.getZoom(),max=z<2.2?0:z<3.2?1:2;for(const m of geoMarkers){const e=m.getElement();e.style.display=+e.dataset.z<=max?'':'none'}}
function updateLegend(points){const lg=document.getElementById('map-legend');if(!lg)return;const civIds=[...new Set(points.map(p=>p.civ).filter(Boolean))];lg.innerHTML=civIds.map(id=>`<span><i style="background:${civColor(id)}"></i>${escape(byId(id)?.title||'')}</span>`).join('')+`<span><i class="ev"></i>حدث</span><span class="legend-geo"><i class="sw-d"></i>صحراء <i class="sw-m"></i>جبال <i class="sw-r"></i>نهر</span>`}
function fitPoints(points){if(!liveMap||!points.length||!window.maplibregl)return;const b=new maplibregl.LngLatBounds();for(const p of points)b.extend(p.point);const w=document.getElementById('map').clientWidth,pad=Math.round(Math.min(130,w*.22));liveMap.fitBounds(b,{padding:{top:80,bottom:70,left:pad,right:pad},maxZoom:3,duration:reduced?0:700})}
function updateMap(fit=false){const sel=document.getElementById('map-selection');if(sel)sel.innerHTML='<h3>التاريخ له مكان.</h3><p>اختر موقعًا في الفترة الحالية لقراءة قصته ومصادره.</p>';const y=FRAMES[mapIndex];document.getElementById('year-label').textContent=dateLabel(y);const slider=document.getElementById('year-slider');slider.value=mapIndex;slider.setAttribute('aria-valuetext',dateLabel(y));document.querySelectorAll('[data-frame]').forEach(x=>x.classList.toggle('active',+x.dataset.frame===mapIndex));const points=activePoints();for(const m of markers)m.remove();markers=[];if(liveMap){for(const p of points){let el=document.createElement('button');el.className=`map-point ${p.type==='event'?'event':''}`;el.style.setProperty('--c',civColor(p.civ));el.innerHTML=`<span>${escape(p.title)}${p.type==='event'?' · '+dateLabel(p.start):''}</span>`;el.setAttribute('aria-label',`استكشف ${p.title}`);el.onclick=()=>selectPoint(p);markers.push(new maplibregl.Marker({element:el,offset:[0,0]}).setLngLat(p.point).addTo(liveMap))}}else updateFallback(points);const list=document.getElementById('map-topic-list');if(list)list.innerHTML=points.length?points.map(p=>`<button data-point="${escape(p.id)}" class="${p.type==='event'?'is-event':''}"><i style="--c:${civColor(p.civ)}"></i>${escape(p.title)}${p.type==='event'?` <small>${dateLabel(p.start)}</small>`:''} ←</button>`).join(''):'<p>لا توجد نتائج لهذه الطبقات أو كلمات البحث في اللقطة المختارة.</p>';const count=document.getElementById('map-count');if(count)count.textContent=`${points.length} مواقع في ${dateLabel(y)}`;if(fit===true)fitPoints(points);updateLegend(points);const hs=liveMap?.getSource('halo');if(hs)hs.setData({type:'FeatureCollection',features:points.filter(p=>p.type!=='event').map(p=>({type:'Feature',properties:{color:civColor(p.civ)},geometry:{type:'Point',coordinates:p.point}}))});if(liveMap)requestAnimationFrame(declutter);const area=document.getElementById('map-period-civs');if(area)area.innerHTML=activeAt(civs,y).map(c=>`<a href="${href(c.id)}">${escape(c.title)} ←</a>`).join('')||'<p>لا توجد حضارات ضمن التغطية الأولية لهذه اللقطة.</p>';document.querySelectorAll('[data-point]').forEach(b=>b.onclick=()=>{const p=points.find(x=>x.id===b.dataset.point);if(p){selectPoint(p);liveMap?.flyTo({center:p.point,zoom:4,duration:reduced?0:900})}})}
function selectPoint(p){const x=byId(p.id),target=document.getElementById('map-selection');target.innerHTML=`<div class="badge">${types[p.type]}</div><h3 style="margin-top:15px">${escape(p.title)}</h3><p>${escape((x?.summary||'موقع مرتبط بالموضوع التاريخي.')+(p.type==='event'?' تاريخ الحدث: '+dateLabel(p.start)+'؛ معروض ضمن سياق الفترة المختارة، وليس حدثًا وقع في سنة اللقطة.':''))}</p><div class="actions"><a class="primary" href="${href(p.id)}">اقرأ الموضوع ←</a>${p.civ?`<a class="text-link" href="${href(p.civ)}">الحضارة المرتبطة</a>`:''}</div>`}
function mountMap(full,topic){const side=document.getElementById('map-side');side.innerHTML=`<span class="badge">استكشاف جغرافي</span><div id="map-selection"><h3>التاريخ له مكان.</h3><p>اختر علامة على الخريطة أو اسمًا من القائمة. حرّك الزمن لتتغير موضوعات الاستكشاف.</p></div>${full?'<input id="map-query" class="map-search" placeholder="ابحث عن مدينة أو حضارة…" aria-label="البحث الجغرافي ضمن اللقطة">':''}<small id="map-count"></small><div class="topic-list" id="map-topic-list"></div>${full?'<details><summary>حضارات الفترة</summary><div id="map-period-civs" class="topic-list"></div></details>':''}`;document.querySelectorAll('[data-frame]').forEach(b=>b.onclick=()=>{mapIndex=+b.dataset.frame;updateMap(true)});document.querySelectorAll('[data-frame-move]').forEach(b=>b.onclick=()=>{mapIndex=Math.max(0,Math.min(6,mapIndex+(+b.dataset.frameMove)));updateMap(true)});document.getElementById('year-slider').oninput=e=>{mapIndex=+e.target.value;updateMap(true)};document.getElementById('map-query')?.addEventListener('input',()=>updateMap());document.querySelectorAll('[data-layer]').forEach(x=>x.onchange=()=>updateMap(true));
try{if(!window.maplibregl)throw Error('MapLibre unavailable');liveMap=new maplibregl.Map({container:'map',center:[43,29],zoom:1.6,minZoom:.6,maxZoom:8,renderWorldCopies:false,attributionControl:true,style:mapStyle()});liveMap.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');liveMap.on('moveend',declutter);liveMap.on('zoom',zoomGeoLabels);liveMap.on('load',mountGeoLabels);if(window.ResizeObserver){const ro=new ResizeObserver(()=>liveMap?.resize());ro.observe(document.getElementById('map'));liveMap.once('remove',()=>ro.disconnect())}liveMap.on('load',()=>{updateMap(!topic);if(topic){const c=civs.find(x=>x.id===topic)||civs.find(x=>x.id===byId(topic)?.civId),p=activePoints().find(x=>x.civ===c?.id||x.id===topic);if(p){selectPoint(p);liveMap.flyTo({center:p.point,zoom:3.5,duration:reduced?0:900})}}});liveMap.on('error',e=>{if(e.error?.message?.includes('WebGL'))fallbackMap()});}catch{fallbackMap()}updateMap()}
let fallbackLand=null;
function fallbackMap(){try{liveMap?.remove()}catch{}liveMap=null;document.getElementById('map').innerHTML='<div class="map-fallback"><svg viewBox="0 0 1000 520" aria-label="خريطة مواقع بديلة"><rect width="1000" height="520" fill="#0c2233"/><g id="fallback-land" fill="#33473b" stroke="#c5a46d" stroke-opacity=".5" stroke-width=".4"></g></svg><div class="fallback-points"></div><p class="fallback-help">عرض بديل عند غياب WebGL. استخدم قائمة المواقع للوصول الكامل إلى المحتوى.</p></div>';fetch('assets/land.geojson').then(r=>r.json()).then(g=>{fallbackLand=g;updateFallback(activePoints())}).catch(()=>toast('تعذر تحميل اليابسة. قائمة المواقع متاحة.'))}
function updateFallback(points){const layer=document.querySelector('.fallback-points');if(!layer)return;const projection=([lng,lat])=>[(lng+180)/360*1000,(90-lat)/180*520];if(fallbackLand){document.querySelector('#fallback-land').innerHTML=fallbackLand.features.map(f=>{const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;return polys.map(poly=>`<path d="${poly.map(ring=>ring.map((c,i)=>{const[x,y]=projection(c);return `${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`}).join(' ')+'Z').join(' ')}"/>`).join('')}).join('')}layer.innerHTML=points.map(p=>{let[x,y]=projection(p.point);return `<button class="fallback-point" style="left:${x/10}%;top:${y/5.2}%" data-fallback-point="${escape(p.id)}">${escape(p.title)}</button>`}).join('');layer.querySelectorAll('button').forEach(b=>b.onclick=()=>selectPoint(points.find(p=>p.id===b.dataset.fallbackPoint)))}
function atlas(params){if(params.has('frame'))mapIndex=Math.max(0,Math.min(6,+params.get('frame')||0));if(params.has('year'))mapIndex=FRAMES.indexOf(nearestFrame(+params.get('year')));main.innerHTML=head('الخريطة التاريخية','استكشف المواقع التي تتوفر لها معلومات ضمن سبع لقطات زمنية. لا تمثل العلامات حدود الدول أو الإمبراطوريات.','أين حدثت القصة؟')+`<div class="container section" style="padding-top:0"><div class="map-options"><label><input data-layer id="layer-city" type="checkbox" checked> المدن</label><label><input data-layer id="layer-event" type="checkbox" checked> أحداث سابقة مرتبطة بالفترة</label><span class="muted">حدود سياسية وطرق تجارة: لم تُدرج لعدم اكتمال بياناتها.</span></div>${mapShell(true)}<p class="map-note">إحداثيات المدن مراكز تقريبية، وليست مواقع دقيقة لجميع أحيائها القديمة. <a class="text-link" href="#/sources">اقرأ منهجية الخرائط ←</a></p></div>`;mountMap(true,params.get('topic'))}
function encyclopedia(params,searchPage=false){currentType=params.get('type')||'all';if(!['all',...Object.keys(types)].includes(currentType))currentType='all';main.innerHTML=head(searchPage?'البحث التاريخي':'الموسوعة','ابدأ بحضارة، أو تتبع مدينة وشخصية وحدثًا. البحث يتجاهل التشكيل واختلاف كتابة الهمزات.')+`<div class="container section" style="padding-top:0"><input id="search" type="search" class="search-box" placeholder="ماذا تريد أن تكتشف؟ جرّب: الأندلس، بغداد، روما…" aria-label="البحث في الموسوعة" value="${escape(params.get('q')||'')}"><div class="filters">${['all','civilization','city','person','event','science'].map(t=>`<button data-type="${t}" class="${t===currentType?'active':''}">${t==='all'?'كل الموضوعات':types[t]}</button>`).join('')}</div><p id="result-count" class="muted" aria-live="polite"></p><div id="results" class="search-results"></div></div>`;document.getElementById('search').oninput=renderResults;document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{currentType=b.dataset.type;document.querySelectorAll('[data-type]').forEach(x=>x.classList.toggle('active',x===b));renderResults()});renderResults()}
function renderResults(){let found=search(items,document.getElementById('search').value,currentType);document.getElementById('result-count').textContent=`${found.length} موضوعات`;document.getElementById('results').innerHTML=found.length?found.map(result).join(''):'<div class="empty"><h3>لم نجد نتيجة.</h3><p>جرّب اسم حضارة أو مدينة بكلمات أقصر، أو اختر «كل الموضوعات».</p></div>'}
function article(id){const x=byId(id);if(!x)return notFound();const c=x.type==='civilization'?x:byId(x.civId);main.innerHTML=head(x.title,x.summary,types[x.type])+`<div class="container section" style="padding-top:0"><div class="article-layout"><article class="article-text">${x.caveat?`<div class="notice"><strong>حدود المعرفة:</strong> ${escape(x.caveat)}</div>`:''}${x.sections.filter(s=>s.text!==x.summary).map(s=>`<section><h2>${escape(s.title)}</h2><p>${escape(s.text)}</p>${s.caveat&&s.caveat!==x.caveat?`<p class="map-note">${escape(s.caveat)}</p>`:""}${s.sourceIds?.length?`<small>مراجع الفقرة: ${s.sourceIds.map(id=>`<a class="gold" href="${escape(sources[id]?.url)}" target="_blank" rel="noopener noreferrer">${escape(sources[id]?.title)} ↗</a>`).join(' · ')}</small>`:''}</section>`).join('')}${x.events?.length?`<section><h2>محطات رئيسية</h2><div class="article-timeline">${x.events.map(e=>`<div><b>${dateLabel(e.year)}</b><p>${e.id&&byId(e.id)?`<a href="${href(e.id)}">${escape(e.title)} ←</a>`:escape(e.title)}</p></div>`).join('')}</div></section>`:''}${x.people?.length?`<section><h2>شخصيات مرتبطة</h2><div class="related">${x.people.map(p=>`<a href="${href(p.id)}">${escape(p.name)} ←</a>`).join('')}</div></section>`:''}${x.quiz?`<section><h2>اختبر فهمك</h2><p>${escape(x.quiz.question)}</p><div class="quiz-options">${x.quiz.options.map((o,i)=>`<button data-article-answer="${i}">${escape(o)}</button>`).join('')}</div><div id="quiz-feedback" class="feedback" role="status" aria-live="polite"></div></section>`:''}<section><h2>موضوعات ذات صلة</h2><div class="related">${(x.related||[]).map(id=>`<a href="${href(id)}">${escape(byId(id)?.title)} ←</a>`).join('')}</div></section><section><h2>المصادر والمراجع</h2>${sourceLinks(x.sources)}</section></article><aside class="article-aside">${motif(c?.id||x.id)}<dl><dt>الفترة</dt><dd>${escape(x.periodLabel)}</dd><dt>المكان</dt><dd>${escape(x.region||c?.region||'انظر الموضوع المرتبط')}</dd><dt>التمثيل الجغرافي</dt><dd>${x.point?'نقطة موقع تقريبية؛ بلا حدود نفوذ':'موضوع مرتبط بالموسوعة'}</dd></dl><div class="actions" style="margin-top:22px"><button id="bookmark">${state.saved.includes(x.id)?'✓ محفوظ':'◇ احفظ الموضوع'}</button>${c?`<a class="text-link" href="#/atlas?topic=${c.id}&frame=${bestFrame(c)}">على الخريطة ⌖</a>`:''}</div></aside></div></div>`;document.getElementById('bookmark').onclick=()=>{if(state.saved.includes(x.id)){state.saved=state.saved.filter(id=>id!==x.id);toast('أزيل من المحفوظات')}else{state.saved.push(x.id);toast('أضيف إلى المحفوظات')}persist();document.getElementById('bookmark').textContent=state.saved.includes(x.id)?'✓ محفوظ':'◇ احفظ الموضوع'};document.querySelectorAll('[data-article-answer]').forEach(b=>b.onclick=()=>{let good=answerIsCorrect(x.quiz,+b.dataset.articleAnswer);document.querySelectorAll('[data-article-answer]').forEach(v=>v.classList.remove('correct','wrong'));b.classList.add(good?'correct':'wrong');document.getElementById('quiz-feedback').textContent=(good?'إجابة صحيحة. ':'حاول مجددًا. ')+x.quiz.explanation})}
function bestFrame(c){let active=FRAMES.filter(y=>c.start<=y&&c.end>=y);return FRAMES.indexOf(active[0]||nearestFrame(c.start))}
function journeys(){main.innerHTML=head('الرحلات التاريخية','تعلم بالفهم: افتح الموضوع، استكشف المكان، ثم أجب لتفتح المحطة التالية. تقدمك محفوظ محليًا في هذا المتصفح.')+`<div class="container section" style="padding-top:0"><div class="journey-grid">${JOURNEYS.map(journeyCard).join('')}</div></div>`}
function journey(id){const j=JOURNEYS.find(x=>x.id===id);if(!j)return notFound();const p=state.journeys[id]||{step:0,done:[]};p.step=validStep(p.step,j.steps.length);p.done=Array.isArray(p.done)?p.done.filter(v=>Number.isInteger(v)&&v>=0&&v<3):[];state.journeys[id]=p;const s=j.steps[p.step],c=byId(s.civ),key=`${id}:${p.step}`,answer=quizAnswers[key];main.innerHTML=head(j.title,j.subtitle,'رحلة تعليمية / تقدمك '+p.done.length+' من 3')+`<div class="container section" style="padding-top:0"><div class="journey-workspace"><aside class="step-list">${j.steps.map((t,i)=>`<button data-step="${i}" class="${i===p.step?'active':''} ${p.done.includes(i)?'done':''}" ${i>0&&!p.done.includes(i-1)?'disabled':''}>0${i+1} · ${t.title}</button>`).join('')}</aside><article class="lesson-card"><span class="badge">المحطة ${p.step+1} / 3</span><h2>${s.title}</h2><p>${s.text}</p><div class="context-graphic">${motif(s.civ)}<div><span class="gold">${s.when||dateLabel(s.year)}</span><p>${s.task}</p><div class="actions"><a class="text-link" href="${href(s.civ)}">افتح الموضوع ←</a><a class="text-link" href="#/atlas?topic=${s.civ}&frame=${bestFrame(c)}">استكشف موقعه ⌖</a>${s.civ==='abbasid'?'<a class="text-link" href="#/city">ادخل بغداد ←</a>':''}</div></div></div><h3 style="margin-top:30px">${s.q}</h3><div class="quiz-options">${s.options.map((o,i)=>`<button data-journey-answer="${i}" class="${answer===i?(i===s.answer?'correct':'wrong'):''}">${o}</button>`).join('')}</div><div class="feedback" id="journey-feedback" role="status" aria-live="polite">${answer!==undefined?(answer===s.answer?'إجابة صحيحة. ':'حاول مجددًا. ')+s.explanation:p.done.includes(p.step)?'أكملت هذه المحطة سابقًا. يمكنك مراجعتها.':''}</div><div class="journey-actions"><button data-back ${p.step===0?'disabled':''}>→ المحطة السابقة</button>${p.step<2?`<button class="primary" data-next ${!p.done.includes(p.step)?'disabled':''}>المحطة التالية ←</button>`:`<a href="#/journeys" class="${p.done.includes(2)?'primary':'secondary'}">${p.done.includes(2)?'✓ أتممت الرحلة':'العودة للرحلات'}</a>`}</div><details style="margin-top:25px"><summary class="muted">مراجع هذه المحطة</summary>${sourceLinks([...c.sources,...(id==='rome'?['roman-republic']:[]),...(id==='caliphates'?byId('andalus')?.sources||[]:[])].filter((x,i,a)=>a.indexOf(x)===i))}</details></article></div></div>`;document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{p.step=+b.dataset.step;persist();journey(id)});document.querySelector('[data-back]').onclick=()=>{p.step--;persist();journey(id)};document.querySelector('[data-next]')?.addEventListener('click',()=>{if(p.done.includes(p.step)){p.step++;persist();journey(id)}});document.querySelectorAll('[data-journey-answer]').forEach(b=>b.onclick=()=>{const idx=+b.dataset.journeyAnswer;quizAnswers[key]=idx;if(idx===s.answer&&!p.done.includes(p.step)){p.done.push(p.step);persist()}journey(id)})}
const landmarks=[{title:'مركز الحكم',x:50,y:45,text:'يربط المخطط بين مركز المدينة ومقر الحكم. تخطيط المدينة المدورة وضع قصر الخليفة والجامع في قلبها. شكل القصر وألوانه في هذا الرسم رمزية، ولا تمثل أثرًا محفوظًا.',q:'ما وظيفة القصر؟',options:['مقر الحكم والإدارة','ميناء بحري','مزرعة خارج المدينة'],answer:0,explanation:'القصر يمثل مركز الحكم. تفاصيل تصميمه في هذا الرسم تعليمية وليست مسحًا أثريًا.'},{title:'الجامع',x:50,y:60,text:'الجامع جزء من مركز المدينة بحسب الروايات التي تستند إليها دراسات إعادة البناء. قربه من القصر يوضح حضور مؤسسات الحكم والعبادة في تخطيط العاصمة. لا يُفهم ترتيب الرسم على أنه قياس دقيق.',q:'ما الذي نستنتجه من رسم الجامع؟',options:['أن كل ارتفاعاته موثقة','وظيفته في المدينة، مع التحفظ على التفاصيل المرئية','أن الصورة تصوير فوتوغرافي'],answer:1,explanation:'الرسم يساعد على فهم الوظيفة. الأبعاد والارتفاعات ليست مثبتة بهذا المخطط.'},{title:'البوابات والاتصال',x:14,y:50,text:'أربع بوابات ربطت المدينة باتجاهات خارجية، وسميت في الروايات بالكوفة والبصرة والشام وخراسان. تمثل نقاط الدخول اتصال العاصمة بمحيطها، وليست حدود الدولة. هذا الرسم لا يثبت اتجاه كل بوابة.',q:'هل البوابة تحدد حدود الخلافة؟',options:['نعم','لا؛ هي مدخل للمدينة فقط','تحدد حدود العراق الحديثة'],answer:1,explanation:'البوابات عناصر في المدينة. حدود الخلافة مسألة جغرافية سياسية أوسع.'},{title:'الممرات والمناطق السكنية',x:64,y:30,text:'تساعد الممرات على ربط المركز بالبوابات والمناطق المحيطة. نمثل الأبنية الصغيرة هنا برموز تعليمية؛ عددها ومواقعها لا يدعيان مطابقة البناء القديم. توسعت بغداد مع الزمن خارج نواة المدينة المدورة.',q:'هل عدد الأبنية المرسومة إحصاء تاريخي؟',options:['نعم','نعم إذا تشابهت ألوانها','لا؛ هي رموز تعليمية'],answer:2,explanation:'العدد في الرسم قرار توضيحي، وليس بيانات أثرية أو تعدادًا للسكان.'}];
function city(selected=0){const l=landmarks[selected];main.innerHTML=head('بغداد: استكشف المدينة المدورة','تصور ثنائي الأبعاد يشرح وظائف المعالم. اختر النقاط أو استخدم الأزرار أدناه.','مدينة السلام / تأسست 762 م')+`<div class="container section" style="padding-top:0"><div class="notice">هذا مخطط فني تعليمي أصلي، وليس صورة أثرية أو خريطة هندسية. المدينة المدورة معروفة من المصادر المكتوبة؛ تفاصيل إعادة البناء محل بحث. مواقع النقاط داخل الرسم توضيحية، لا إحداثيات فعلية.</div><div class="city-workspace"><div><div class="city-scene">${citySVG()}${landmarks.map((t,i)=>`<button class="hotspot ${selected===i?'active':''}" style="left:${t.x}%;top:${t.y}%" data-landmark="${i}" aria-label="${t.title}">${state.city.includes(i)?'✓':i+1}</button>`).join('')}</div><div class="filters" style="margin-top:20px">${landmarks.map((t,i)=>`<button data-landmark="${i}" class="${selected===i?'active':''}">${t.title}</button>`).join('')}</div><small>فهمت ${state.city.length} من 4 معالم. الحفظ محلي على هذا المتصفح.</small></div><article class="landmark-detail" aria-live="polite"><span class="badge">${selected+1} / 4 · إعادة بناء تعليمية</span><h2 style="margin-top:18px">${l.title}</h2><p>${l.text}</p><h3>${l.q}</h3><div class="quiz-options">${l.options.map((o,i)=>`<button data-city-answer="${i}">${o}</button>`).join('')}</div><div id="city-feedback" class="feedback" role="status"></div><a class="text-link" href="${href('abbasid')}">اقرأ تاريخ العباسيين ←</a><details style="margin-top:22px"><summary>مصادر المخطط</summary>${sourceLinks(['city-archnet','city-cambridge','city-khan'])}</details></article></div></div>`;document.querySelectorAll('[data-landmark]').forEach(b=>b.onclick=()=>city(+b.dataset.landmark));document.querySelectorAll('[data-city-answer]').forEach(b=>b.onclick=()=>{let good=+b.dataset.cityAnswer===l.answer;document.querySelectorAll('[data-city-answer]').forEach(v=>v.classList.remove('correct','wrong'));b.classList.add(good?'correct':'wrong');document.getElementById('city-feedback').textContent=(good?'أحسنت. ':'حاول مجددًا. ')+l.explanation;if(good&&!state.city.includes(selected)){state.city.push(selected);persist();document.querySelectorAll('[data-landmark]').forEach(v=>{if(v.classList.contains('hotspot')&&+v.dataset.landmark===selected)v.textContent='✓'});document.querySelector('.city-workspace small').textContent=`فهمت ${state.city.length} من 4 معالم. الحفظ محلي على هذا المتصفح.`}})}
function saved(){const list=items.filter(x=>state.saved.includes(x.id));main.innerHTML=head('محفوظاتي','مساحة خاصة للموضوعات التي تريد العودة إليها. تُحفظ في هذا المتصفح فقط، وليست حسابًا سحابيًا.')+`<div class="container section" style="padding-top:0">${list.length?`<div class="search-results">${list.map(result).join('')}</div>`:'<div class="empty"><h3>ابدأ مجموعتك التاريخية.</h3><p>افتح أي موضوع واضغط «احفظ الموضوع» لتجده هنا لاحقًا.</p><a class="primary" href="#/encyclopedia">استكشف الموسوعة ←</a></div>'}</div>`}
function sourcesPage(){main.innerHTML=head('المصادر والمنهجية','المعلومة أهم من جمال الخريطة. نحدد ما نعرفه، وما نقدّره، وما نعرضه لتسهيل الفهم.')+`<div class="container section article-text" style="padding-top:0"><section><h2>تغطية واضحة</h2><p>تضم النسخة ${civs.length} موضوعات حضارية وصفحات مرتبطة ومدنًا وأحداثًا وشخصيات ومدخلين للعلوم والتقنيات. لا تدعي تقديم تاريخ البشرية كاملًا. حدود الفترات التعليمية مذكورة في كل موضوع.</p></section><section><h2>كيف نرسم الخريطة؟</h2><p>نستخدم مواقع مدن تقريبية فوق طبقة اليابسة من Natural Earth (ملك عام). لا نرسم حدود إمبراطوريات، ولا نستخدم حدود الدول الحديثة بديلًا عنها. اليابسة تمثل جغرافيا عامة معاصرة؛ تغير السواحل والأنهار عبر الزمن غير ممثل. العلامة مرتبطة بموضوع الحضارة في اللقطة، ولا تعني أن المدينة لم توجد خارجها.</p><p>اللّقطات: ${FRAMES.map(dateLabel).join('، ')}. النقاط لا تمثل تعداد جميع المدن. طبقة الأحداث تعرض أحداثًا سابقة لسنة اللقطة مرتبطة بموضوعات الحضارات الظاهرة ولها موقع محدد؛ تاريخ كل حدث يظل مستقلًا عن تاريخ اللقطة، وقد تكون الطبقة فارغة.</p></section><section><h2>الفترات واليقين</h2><p>نكتب «نحو» للتواريخ التقريبية، ونفصل تاريخ المدينة عن تاريخ الدولة. لا توجد سنة صفر في التأريخ التقليدي. بداية الجمهورية الرومانية مثال على تأريخ تقليدي لا تُعامل تفاصيله المبكرة بوصفها جميعًا متساوية اليقين.</p><div class="notice">موثق: تؤيده المصادر المدرجة. تقريبي: التاريخ أو الإحداثيات تقدير عام. محل بحث: توجد اختلافات تفسيرية. تصور فني: رسم تعليمي لا يثبت مظهر المباني.</div></section><section><h2>الصور والمخططات</h2><p>مشهد البداية تصور فني مولد، يجمع رموزًا تاريخية؛ ليس مكانًا أثريًا واحدًا. رموز البطاقات ومخطط بغداد رسوم أصلية. مخطط بغداد تعليمي غير مقيَّس؛ تعتمد مناقشة إعادة البناء على المصادر والدراسة الأكاديمية المدرجة.</p></section><section><h2>الخصوصية والتقدم</h2><p>لا تتطلب الرحلات حسابًا. المحفوظات ونتائج المحطات محفوظة محليًا تحت مفتاح atlas-v1؛ مسح بيانات المتصفح يمحوها، ولا تنتقل تلقائيًا إلى جهاز آخر. إذا منع المتصفح التخزين تستمر الجلسة مع تنبيه واضح.</p></section><section><h2>مرجع كل موضوع</h2><p>صغنا المحتوى العربي خصيصًا للمشروع، مع روابط مصادر لكل موضوع وفقرة عند توفر الربط. المراجع ليست ترخيصًا لنسخ المواد الأصلية. لم يراجع مؤرخ بشري مستقل جميع النصوص؛ هذه نسخة أولى قابلة للتحسين.</p>${sourceLinks(Object.keys(sources))}</section><section><h2>الأصول التقنية ورخصها</h2><p><a class="gold" target="_blank" rel="noopener" href="https://www.naturalearthdata.com/about/terms-of-use/">Natural Earth: ملك عام ↗</a> · <a class="gold" href="assets/MAPLIBRE-LICENSE.txt">MapLibre GL JS 5.6.1: BSD-3-Clause</a> · <a class="gold" href="assets/FONT-LICENSE.txt">IBM Plex Sans Arabic: SIL Open Font License</a></p></section></div>`}
const researchRows=[['GeaCron','أطلس منذ 3000 ق.م؛ ممالك ومعارك وحملات وقاعدة خرائط متجهة.','التطبيق مضمن داخل iframe؛ لم تُختبر تفاعلاته.','https://geacron.com/home-en/'],['TimeMaps','تتابع خرائط عالمي وإقليمي ومحلي، ومراجع تعليمية، و20 تاريخًا مشتركًا.','تعذر تحميل الرئيسية؛ وصلت صفحة شرح الأطلس.','https://timemaps.com/the-timemaps-atlas-of-world-history/'],['Chronas','النتيجة التعريفية تذكر اشتراط WebGL.','صفحة التطبيق الحالية فارغة في القراءة؛ التفاعل غير مفحوص.','https://www.chronas.org/'],['World History Encyclopedia','موسوعة وخرائط وخط زمني ومصادر أولية وسياسة تحرير.','فحص صفحات عامة؛ لا قياس للنتائج التعليمية.','https://www.worldhistory.org/static/editorial-policy/'],['World-Civ','سحب وتشغيل الزمن، مناطق قابلة للنقر، مرشحات، وأحداث؛ رخص ومصادر ظاهرة.','تحقق من وصف الصفحة، دون تجربة الخريطة.','https://world-civ.com/'],['Geographic History','صفحة عربية تصف خرائط سنوية وأحداثًا وألعاب جغرافية.','الوصف يخص تطبيق الهاتف؛ لم يُثبت تكافؤ تجربة الويب.','https://geographichistory.app/ar/'],['Atlas Anatolia','مواقع أثرية وعصور ورحلات وإعادة بناء وتقييم للأدلة.','الأقسام موجودة في النص؛ وظائفها لم تُختبر بالمتصفح.','https://atlasanatolia.com/ar'],['بوابات التاريخ','بحث عربي ومسطرة زمنية ومقالات وقادة ومعارك.','ظهر Loading للخريطة في النص، وأعداد المقالات غير متسقة.','https://gatesofhistory.com/ar']];
function researchPage(){main.innerHTML=head('ما الذي تعلمناه من المنافسين؟','مقارنة عملية قبل التنفيذ · 12 أكتوبر 2026 · فحص صفحات عامة، وليس اختبار استخدام كاملًا.')+`<div class="container section article-text" style="padding-top:0"><div class="table-wrap"><table><thead><tr><th>الموقع</th><th>الميزة التي تحققنا منها</th><th>حدود الفحص</th></tr></thead><tbody>${researchRows.map(r=>`<tr><td><a href="${r[3]}" target="_blank" rel="noopener">${r[0]} ↗</a></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div><section><h2>أفضل خمس أفكار</h2><ol><li>ربط الموقع والفترة والموضوع (TimeMaps).</li><li>عنصر زمن واضح بجانب الخريطة (GeaCron وWorld-Civ).</li><li>تمييز درجة اليقين والتصور الفني (Atlas Anatolia).</li><li>تنظيم الموضوعات والمراجع والمواد التعليمية (WHE).</li><li>بحث عربي يتصل بالموسوعة والخريطة (بوابات التاريخ).</li></ol></section><section><h2>مشكلات مرصودة وتوصيات</h2><p>يوضح TimeMaps أن الفجوات بين لقطاته قد تتجاوز أحداثًا كبيرة؛ لذلك أضفنا رحلات تشرح التحول. اشتراط WebGL قد يحد الوصول في بعض البيئات؛ لذلك وفرنا قائمة المواقع وعرضًا بديلًا. ظهرت أعداد مقالات متباينة في صفحة بوابات التاريخ؛ لذلك نحسب أعداد ATLAS من بياناته الفعلية.</p><p>ازدحام الأقسام قد يربك البداية، لكنه استنتاج تصميمي هنا لا نتيجة اختبار مستخدم. اخترنا أربع وجهات رئيسية ومراجع داخل كل موضوع.</p></section><section><h2>فرص التميز الواقعية</h2><p>الخريطة والرحلات والأسئلة وإعادة البناء موجودة لدى منافسين. التميز المقترح ليس اختراعها، بل تجربة عربية متماسكة، تعليم مختصر، بيانات محدودة صادقة، وأسئلة تفسر أخطاء الفهم. لم نقس الأثر التعليمي بعد.</p></section><section><h2>كيف انعكست الدراسة على التنفيذ؟</h2><p>سبع فترات محددة بدل شريط يوحي ببيانات لكل سنة. نقاط مدن بدل حدود مختلقة. مراجع بجانب الفقرات. تقدم يحفظ بعد إجابة صحيحة، ومخطط يميز الفن عن الدليل الأثري. لم ننسخ تصميمًا أو أصلًا أو محتوى من هذه المنصات.</p><a class="text-link" href="COMPETITOR_RESEARCH.md">اقرأ التقرير التفصيلي ←</a></section></div>`}
function notFound(){main.innerHTML=head('الموضوع غير موجود','قد يكون الرابط غير صحيح. يمكنك البحث عن الموضوع أو العودة إلى الموسوعة.')+'<div class="container section"><a class="primary" href="#/encyclopedia">الموسوعة ←</a></div>'}
function route(){for(const m of markers)m.remove();markers=[];for(const m of geoMarkers)m.remove();geoMarkers=[];if(liveMap){liveMap.remove();liveMap=null}const hash=location.hash.slice(1)||'/',[path,query]=hash.split('?'),parts=path.split('/').filter(Boolean),params=new URLSearchParams(query||'');document.querySelector('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href').split('/')[1]===parts[0]));switch(parts[0]){case undefined:home();break;case'atlas':atlas(params);break;case'encyclopedia':encyclopedia(params);break;case'search':encyclopedia(params,true);break;case'topic':article(decodeURIComponent(parts[1]||''));break;case'journeys':journeys();break;case'journey':journey(parts[1]);break;case'city':city();break;case'saved':saved();break;case'sources':sourcesPage();break;case'research':researchPage();break;default:notFound()}if(!reduced&&window.IntersectionObserver){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('reveal');observer.unobserve(e.target)}},{threshold:.08});document.querySelectorAll('main>.section,main>.container.section').forEach(el=>observer.observe(el))}window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});document.title=`${main.querySelector('h1')?.textContent||'اكتشف العالم عبر الزمن'} | أطلس`}
function adapt(raw){sources=Object.fromEntries(raw.sources.map(s=>[s.id,s]));civs=raw.civilizations.map(c=>({...c,start:c.startYear,end:c.endYear,point:c.coordinates,periodLabel:c.period,sources:c.sourceIds,related:[c.cityId,...c.events.filter(e=>raw.entries.some(x=>x.id===e.id)).map(e=>e.id),...c.people.map(p=>p.id)]}));items=[...civs,...raw.entries.map(x=>{const c=civs.find(c=>c.cityId===x.id||c.people.some(p=>p.id===x.id)||c.events.some(e=>e.id===x.id)||x.relatedIds?.includes(c.id));return {...x,start:x.startYear||x.year||c?.start||-1,end:x.endYear||x.year||c?.end||1,point:x.coordinates,region:c?.region,civId:c?.id,periodLabel:x.period||x.dateLabel||(x.year?dateLabel(x.year):c?.periodLabel)||'انظر الموضوع',sources:x.sourceIds,related:x.relatedIds||[],sections:x.sections||[]}})];sources['city-archnet']={id:'city-archnet',title:'Archnet — Al-Mansur’s Round City of Baghdad',url:'https://www.archnet.org/sites/3826',type:'مرجع معماري؛ الصفحة المباشرة حجبت الوصول أثناء الفحص'};sources['city-cambridge']={id:'city-cambridge',title:'IRAQ — Images of Round Baghdad: An Analysis of Reconstructions',url:'https://www.cambridge.org/core/journals/iraq/article/images-of-round-baghdad-an-analysis-of-reconstructions-by-architectural-historians/8BD21CCA3B37DB2906D47749F0C0A99F',type:'دراسة أكاديمية؛ اطلعنا على الملخص'};sources['city-khan']={id:'city-khan',title:'Khan Academy — The founding of Baghdad',url:'https://www.khanacademy.org/humanities/art-islam/chronological-periods-islamic/islamic-art-medieval/a/the-founding-of-baghdad',type:'مادة تعليمية'};validateContent(items,sources)}
document.querySelector('.menu-toggle').onclick=e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))};
fetch('content.json').then(r=>{if(!r.ok)throw Error('content loading');return r.json()}).then(raw=>{DATA=raw;adapt(raw);window.addEventListener('hashchange',route);route()}).catch(e=>{console.error(e);main.innerHTML='<div class="container section empty"><h1>تعذر تحميل المحتوى.</h1><p>أعد المحاولة. إذا استمر الخطأ تحقق من اتصالك.</p><button id="retry">أعد المحاولة</button></div>';document.getElementById('retry').onclick=()=>location.reload()});
